<?php
/**
 * ArneIron icon pack — the API. GENERATED by ops/release/build-icon-pack.py from
 * design/theme-build/icon-pack/icons-api.php.tmpl; edit the template, not this file.
 *
 * One registry (slug -> SVG), shared by the theme chrome and the ArneIron Blocks
 * plugin, each through its OWN prefixed copy so neither depends on the other:
 * the theme renders complete without the plugin, and the plugin works under any
 * theme. Icons are drawn on a 24 px grid in currentColor, so they take the
 * colour and size of the text around them. Two drawing styles share the grid:
 * the default (stroke 1.75, round caps/joins) and ArneIron VISOR (data
 * 'style' => 'visor': stroke 2, square caps, miter joins, class
 * arneiron-icon--visor). A VISOR icon has at most one "retina" accent shape,
 * coloured by --arneiron-icon-accent, else the theme accent preset, else
 * currentColor.
 *
 *   arneiron_icon( 'agent' )                     decorative <svg aria-hidden="true">
 *   arneiron_icon( 'agent', array( 'label' => 'AI agent' ) ) role="img" + <title>
 *   arneiron_icon_or_glyph( $value )             slug or alias -> SVG; anything else
 *                                              (a legacy glyph such as "◆") is
 *                                              returned as escaped text, unchanged.
 *
 * Filter `arneiron_icon_pack` to add or replace icons (same shape as the data file).
 *
 * @package ArneIron
 */

if ( ! defined( 'ABSPATH' ) ) {
	exit;
}

if ( ! function_exists( 'arneiron_icon_pack' ) ) {
	/**
	 * The registry: array( 'icons' => slug => array( label, category, keywords, body ), 'aliases' => alias => slug ).
	 *
	 * @return array
	 */
	function arneiron_icon_pack() {
		static $pack = null;
		if ( null === $pack ) {
			$data = require __DIR__ . '/icon-pack-data.php';
			$pack = (array) apply_filters( 'arneiron_icon_pack', is_array( $data ) ? $data : array() );
			$pack += array(
				'icons'   => array(),
				'aliases' => array(),
			);
		}
		return $pack;
	}
}

if ( ! function_exists( 'arneiron_icon_slug' ) ) {
	/**
	 * Resolve a stored value to a registry slug: the slug itself, a known alias
	 * (Lucide name, Font Awesome class such as "fas fa-handshake"), or '' when the
	 * value is not an icon name (e.g. a legacy text glyph).
	 *
	 * @param string $value Stored icon value.
	 * @return string
	 */
	function arneiron_icon_slug( $value ) {
		$value = strtolower( trim( (string) $value ) );
		if ( '' === $value || ! preg_match( '/^[a-z0-9 _-]+$/', $value ) ) {
			return '';
		}
		$pack = arneiron_icon_pack();
		foreach ( preg_split( '/\s+/', $value ) as $token ) {
			if ( in_array( $token, array( 'fa', 'fas', 'far', 'fab', 'fa-solid', 'fa-regular' ), true ) ) {
				continue;
			}
			if ( isset( $pack['icons'][ $token ] ) ) {
				return $token;
			}
			if ( isset( $pack['aliases'][ $token ] ) && isset( $pack['icons'][ $pack['aliases'][ $token ] ] ) ) {
				return $pack['aliases'][ $token ];
			}
		}
		return '';
	}
}

if ( ! function_exists( 'arneiron_icon_allowed_html' ) ) {
	/**
	 * A wp_kses() allow-list for this pack's SVG, for callers that kses a larger
	 * fragment containing icons (kses lower-cases `viewBox`, which HTML parsers
	 * restore for inline SVG).
	 *
	 * @return array
	 */
	function arneiron_icon_allowed_html() {
		$shape = array(
			'd'               => true,
			'cx'              => true,
			'cy'              => true,
			'r'               => true,
			'rx'              => true,
			'ry'              => true,
			'x'               => true,
			'y'               => true,
			'x1'              => true,
			'x2'              => true,
			'y1'              => true,
			'y2'              => true,
			'width'           => true,
			'height'          => true,
			'points'          => true,
			'fill'            => true,
			'stroke'          => true,
			'stroke-width'    => true,
			'stroke-linecap'  => true,
			'stroke-linejoin' => true,
			'transform'       => true,
			'class'           => true,
			'style'           => true,
		);
		return array(
			'svg'      => array(
				'xmlns'           => true,
				'viewbox'         => true,
				'width'           => true,
				'height'          => true,
				'fill'            => true,
				'stroke'          => true,
				'stroke-width'    => true,
				'stroke-linecap'  => true,
				'stroke-linejoin' => true,
				'stroke-miterlimit' => true,
				'class'           => true,
				'role'            => true,
				'aria-hidden'     => true,
				'aria-label'      => true,
				'focusable'       => true,
				'data-icon'       => true,
			),
			'title'    => array(),
			'g'        => $shape,
			'path'     => $shape,
			'circle'   => $shape,
			'ellipse'  => $shape,
			'rect'     => $shape,
			'line'     => $shape,
			'polyline' => $shape,
			'polygon'  => $shape,
		);
	}
}

if ( ! function_exists( 'arneiron_icon' ) ) {
	/**
	 * One icon as an inline <svg>, or '' for an unknown slug.
	 *
	 * The markup is safe to echo: the shapes come from the generated data file
	 * (validated by build-icon-pack.py to shape elements with numeric/path
	 * attributes only), the class and label are escaped here. It is not passed
	 * through wp_kses() because kses lower-cases `viewBox`.
	 *
	 * @param string $name Slug or alias.
	 * @param array  $args size (px, default 24), class, label (non-empty => role="img").
	 * @return string
	 */
	function arneiron_icon( $name, $args = array() ) {
		$slug = arneiron_icon_slug( $name );
		if ( '' === $slug ) {
			return '';
		}
		$pack = arneiron_icon_pack();
		$args = wp_parse_args(
			$args,
			array(
				'size'  => 24,
				'class' => '',
				'label' => '',
			)
		);
		$size  = max( 8, (int) $args['size'] );
		$visor = isset( $pack['icons'][ $slug ]['style'] ) && 'visor' === $pack['icons'][ $slug ]['style'];
		$class = trim( 'arneiron-icon arneiron-icon--' . $slug . ( $visor ? ' arneiron-icon--visor' : '' ) . ' ' . $args['class'] );
		$label = trim( (string) $args['label'] );
		$a11y  = '' === $label
			? ' aria-hidden="true" focusable="false"'
			: ' role="img" aria-label="' . esc_attr( $label ) . '"';
		return '<svg xmlns="http://www.w3.org/2000/svg" viewBox="0 0 24 24" width="' . $size . '" height="' . $size . '"'
			. ( $visor
				? ' fill="none" stroke="currentColor" stroke-width="2" stroke-linecap="square" stroke-linejoin="miter" stroke-miterlimit="10"'
				: ' fill="none" stroke="currentColor" stroke-width="1.75" stroke-linecap="round" stroke-linejoin="round"' )
			. ' class="' . esc_attr( $class ) . '" data-icon="' . esc_attr( $slug ) . '"' . $a11y . '>'
			. ( '' === $label ? '' : '<title>' . esc_html( $label ) . '</title>' )
			. $pack['icons'][ $slug ]['body']
			. '</svg>';
	}
}

if ( ! function_exists( 'arneiron_icon_or_glyph' ) ) {
	/**
	 * Back-compat renderer for a free-text icon slot: a slug/alias becomes the SVG,
	 * anything else (a legacy glyph such as "◈") is returned as escaped text.
	 *
	 * @param string $value Stored icon value.
	 * @param array  $args  See arneiron_icon().
	 * @return string
	 */
	function arneiron_icon_or_glyph( $value, $args = array() ) {
		$svg = arneiron_icon( $value, $args );
		return '' !== $svg ? $svg : esc_html( (string) $value );
	}
}
